export function searchCid(term: string, system?: "CID-10" | "CID-11"): CidCode[] {
  const q = term.trim().toLowerCase();
  return cidCodes.filter(
    (c) =>
      (!system || c.system === system) &&
      (!q || c.code.toLowerCase().includes(q) || c.title.toLowerCase().includes(q)),
  );
}

export function cidLabel(code: string): string {
  const found = cidCodes.find((c) => c.code === code);
  return found ? `${found.code} — ${found.title}` : code;
}
